H = ['المفاهيم والأحداث التاريخية', 'تحليل النصوص والخرائط']
E = ['المفاهيم البيئية', 'تحليل الأشكال والخرائط']

lesson(2450,
 'امتد عصر النباهنة نحو خمسة قرون تخللتها فترات حكم الأئمة، وقُسّم إلى عصرين، واتسم بالتذبذب بين القوة والضعف وبتجزئة سياسية غابت معها الوحدة الوطنية.',
 [('يرسم مخططًا لفترتي العصر النبهاني', ['العصر الأول: 549هـ/1154م – 906هـ/1500م، ومن ملوكه سليمان بن المظفر وابنه سليمان.', 'العصر الثاني: 964هـ/1556م – 1034هـ/1624م، ومن ملوكه سلطان بن محسن وأخوه فلاح.']),
  ('يفسّر شح المصادر التاريخية عن عصر النباهنة', ['لا يوجد مصدر تاريخي يمدنا بتفاصيله.', 'نستقي المعلومات من كتب الفقه والأدب والرحلات، ومنها ديوان الملك سليمان بن سليمان.']),
  ('يدلّل على غياب الوحدة الوطنية', ['استقل كل ملك بمملكة، وقامت بينها صراعات على السلطة.', 'وقعت معارك مع المناوئين من الأئمة كالإمام أبي الحسن بن خميس.', 'نتيجة الصراعات: تعرض عُمان للغزو الخارجي.'])],
 [('العصر النبهاني', 'فترة حكم النباهنة لعُمان، امتدت نحو خمسة قرون وقُسّمت إلى عصرين'), ('الوحدة الوطنية', 'تماسك أبناء الوطن واجتماعهم تحت قيادة واحدة'), ('المناوئون', 'المعارضون لسلطة الحاكم والمنازعون له'), ('التجزئة السياسية', 'انقسام البلاد إلى ممالك صغيرة يحكم كلًا منها حاكم مستقل')],
 ['تعدد مسميات الحكام (سلطان، ملك، إمام) دليل على تنوع الأنظمة التي حكمت عُمان.', 'الصراع بين الملك سليمان بن سليمان وأخيه حسام انتهى بمقتل حسام.', 'الانقسام الداخلي يُطمع الغزاة.'],
 'التمييز بين عصري النباهنة، وتفسير شح المصادر، والربط بين التجزئة وضعف عُمان.', H,
 'تخيّل بيتًا كبيرًا اختلف أفراده وانقسموا، فسكن كل واحد غرفة وأغلق بابها. هكذا كانت عُمان في عصر النباهنة: كل ملك يحكم جزءًا منها، فضعفت البلاد وطمع فيها الغرباء. وكان هذا العصر طويلًا جدًا (نحو خمسة قرون)، لذلك قسّمه المؤرخون إلى عصرين.',
 [('قُسّم العصر النبهاني إلى ...... عصرين', 'عصرين'), ('انتهى العصر النبهاني الأول عام ......م', '1500'), ('من أبرز ملوك العصر النبهاني الثاني ...... بن محسن', 'سلطان'), ('من مصادر تاريخ عصر النباهنة كتب الفقه والأدب و......', 'الرحلات')],
 [('امتد عصر النباهنة نحو (خمسة قرون / قرنين).', 'خمسة قرون'), ('قتل الملك سليمان بن سليمان أخاه (حسامًا / فلاحًا).', 'حسامًا'), ('من نتائج الصراعات الداخلية (الغزو الخارجي / الوحدة الوطنية).', 'الغزو الخارجي'), ('ديوان الملك سليمان بن سليمان مصدر من مصادر (عصر النباهنة / عصر البوسعيد).', 'عصر النباهنة')],
 [('علّل شح المصادر التاريخية عن عصر النباهنة.', 'كثرة الصراعات الداخلية التي قللت الاهتمام بالتدوين، وضياع المخطوطات بفعل الحروب والعوامل الطبيعية.'), ('اذكر نتيجتين للتجزئة السياسية في عصر النباهنة.', 'غياب الوحدة الوطنية، وتعرض عُمان للغزو الخارجي.'), ('ما دلالة تعدد مسميات حكام عُمان؟', 'تنوع الأنظمة التي حكمت عُمان.')],
 [('امتد عصر النباهنة نحو خمسة قرون.', True, 'تخللته فترات حكم الأئمة، وقُسّم إلى عصرين.'), ('عاشت عُمان في عصر النباهنة وحدة وطنية تامة.', False, 'شهدت تجزئة واضحة؛ استقل كل ملك بمملكة يحكمها.'), ('العصر النبهاني الثاني أطول من الأول.', False, 'الأول نحو 350 سنة (1154–1500م) والثاني نحو 70 سنة (1556–1624م).'), ('من مصادر تاريخ النباهنة كتب الرحلات.', True, 'لعدم وجود مصدر تاريخي مفصل نستقي المعلومات من كتب الفقه والأدب والرحلات.')],
 [('الصراعات الداخلية', 'تعرض عُمان للغزو الخارجي', 'الانقسام يُضعف البلاد ويُطمع الغزاة.'), ('ضياع المخطوطات بالحروب', 'شح المصادر التاريخية', 'فقدان المصادر يصعّب تتبع الأحداث.')],
 ('من التجزئة إلى الغزو في عصر النباهنة', ['استقلال كل ملك بمملكة', 'صراعات على السلطة بين الممالك', 'معارك مع المناوئين من الأئمة', 'تعرض عُمان للغزو الخارجي']))

lesson(2451,
 'تنوعت علاقات عُمان الخارجية في العصر النبهاني بين علاقات وطيدة واضطراب، وامتد أثرها إلى شرق إفريقيا، وبرزت مظاهر حضارية اجتماعية وعمرانية.',
 [('يصنّف علاقات عُمان الخارجية', ['علاقة وطيدة مع اليمن: تبادل الملك أبو المعالي كهلان الهدايا مع ملكها.', 'علاقة مضطربة مع مملكة هرمز: غزا الهرامزة عُمان أكثر من مرة كغزو توران شاه.']),
  ('يشرح علاقة عُمان بشرق إفريقيا', ['هاجر الملك سليمان بن نبهان بن مظفر إلى جزيرة باتي وتزوج ابنة زعيمها.', 'بدأ حكم النباهنة للجزيرة بابنه محمد، واستمر في أبنائه.']),
  ('يذكر المظاهر الحضارية الاجتماعية والعمرانية', ['أشاد ابن بطوطة بقيم العُمانيين: تواضع الملك والكرم والمصافحة بعد الصلاة.', 'من المراكز الحضارية: نزوى وبُهلا (العصر الأول) ومقنيات (العصر الثاني).', 'من الاستحكامات: حصن الأسود في مقنيات بولاية عبري.'])],
 [('مملكة هرمز', 'مملكة قامت في جزيرة هرمز قرب الساحل الفارسي، وبسطت نفوذها على أجزاء من سواحل الخليج العربي وعُمان'), ('جزيرة باتي', 'جزيرة على ساحل شرقي إفريقيا (كينيا حاليًا) حكمها النباهنة'), ('المركز الحضاري', 'مدينة يتخذها الحاكم مقرًا ويهتم بتطويرها وعمرانها'), ('الاستحكامات الحربية', 'القلاع والحصون المبنية للدفاع')],
 ['ابن بطوطة رحالة زار عُمان في عصر النباهنة.', 'حصن الأسود حصن منيع مرتفع في مقنيات.', 'تنوع العلاقات الخارجية دليل على تقبّل الآخر.'],
 'التمييز بين العلاقات الوطيدة والمضطربة، وربط باتي بالنباهنة، واستخراج القيم من نص ابن بطوطة.', H,
 'كانت عُمان في عصر النباهنة كجار له أصدقاء ومنافسون: صديقه اليمن يتبادل معه الهدايا، ومنافسه هرمز يهاجمه أحيانًا. وسافر أحد ملوكها إلى جزيرة باتي في إفريقيا فتزوج هناك وصار أبناؤه ملوكًا عليها. وزار الرحالة ابن بطوطة عُمان فأعجبته أخلاق أهلها وكرمهم.',
 [('العلاقة بين عُمان واليمن في العصر النبهاني كانت ......', 'وطيدة'), ('غزا الملك ...... شاه عُمان من هرمز', 'توران'), ('هاجر الملك سليمان بن نبهان إلى جزيرة ......', 'باتي'), ('يقع حصن الأسود في ...... بولاية عبري', 'مقنيات')],
 [('جزيرة باتي تتبع حاليًا (كينيا / تنزانيا).', 'كينيا'), ('العلاقة مع هرمز كانت (مضطربة / وطيدة).', 'مضطربة'), ('من المراكز الحضارية في العصر النبهاني الأول (نزوى وبُهلا / الرستاق ومسقط).', 'نزوى وبُهلا'), ('الرحالة الذي وصف عادات العُمانيين في عصر النباهنة (ابن بطوطة / ابن ماجد).', 'ابن بطوطة')],
 [('اذكر قيمتين أشاد بهما ابن بطوطة.', 'تواضع الملك، وكرم أهل عُمان (أو مصافحة بعضهم بعضًا بعد صلاتي الفجر والعصر).'), ('كيف بدأ حكم النباهنة لجزيرة باتي؟', 'تزوج الملك سليمان بن نبهان ابنة زعيم الجزيرة، فأنجبت له محمدًا الذي بدأ به حكم النباهنة لها.'), ('صنّف علاقة عُمان مع كل من اليمن وهرمز.', 'اليمن: وطيدة. هرمز: مضطربة.')],
 [('كانت العلاقة بين عُمان ومملكة هرمز وطيدة دائمًا.', False, 'شهدت اضطرابًا؛ غزا الهرامزة عُمان أكثر من مرة.'), ('امتد حكم النباهنة إلى جزيرة باتي في شرق إفريقيا.', True, 'بدأ بمحمد ابن الملك سليمان بن نبهان، واستمر في أبنائه.'), ('حصن الأسود من استحكامات النباهنة الحربية.', True, 'يقع في مقنيات بولاية عبري، وهو حصن منيع مرتفع.'), ('وصف ابن بطوطة أهل ظفار بالبخل مع الغرباء.', False, 'وصفهم بالتواضع وحسن الخلق ومحبة الغرباء وتقديم الضيافة.')],
 [('اليمن', 'علاقة وطيدة', 'تبادل الهدايا بين الملكين.'), ('مملكة هرمز', 'علاقة مضطربة', 'غزوات متكررة لعُمان.')],
 ('قيام حكم النباهنة في جزيرة باتي', ['هجرة الملك سليمان بن نبهان إلى باتي', 'زواجه من ابنة زعيم الجزيرة', 'ولادة ابنه محمد', 'بدء حكم النباهنة للجزيرة واستمراره في أبنائه']))

lesson(2452,
 'شهد العصر النبهاني تطورًا في النظام الإداري والعلمي والاقتصادي، ثم تعرضت عُمان للغزو البرتغالي منذ 1507م فقاومه العُمانيون رغم الانقسام.',
 [('يفسّر تطور النظام الإداري', ['تطور بفضل جهود الحكام والعلماء.', 'تكونت المحكمة من رئيس القضاة وقاضٍ وكاتب الحكم ووكلاء المدعي والمدعى عليه.']),
  ('يعدّد المنجزات العلمية', ['قرّب الملوك العلماء وأكرموا الشعراء، واشتهر بعضهم بالشعر كسليمان بن سليمان.', 'البحار أحمد بن ماجد السعدي ومؤلفه «النونية الكبرى»، وديوان الكيذاوي.']),
  ('يحلّل العلاقات التجارية', ['من الهند: التوابل وخشب الساج والأرز.', 'من الصين: الحرير. ومن شرق إفريقيا: العاج والخشب والعنبر والجلود.']),
  ('يتتبع الغزو البرتغالي ومقاومته', ['وصل البرتغاليون جزر الحلانيات 1507م وعاثوا فسادًا في المدن الساحلية.', 'أضعفوا التجارة بالسيطرة على الموانئ والسلع.', 'ثورة 1521م (30 نوفمبر) شملت أغلب المدن الساحلية.'])],
 [('المحكمة', 'جهاز القضاء المكون من رئيس القضاة والقاضي وكاتب الحكم والوكلاء'), ('المخطوطة', 'كتاب مكتوب باليد قبل الطباعة'), ('العنبر', 'مادة عطرية جُلبت من شرق إفريقيا'), ('ألفونسو دي البوكيرك', 'من أشهر قادة الحملات البرتغالية إلى المشرق')],
 ['النونية الكبرى لأحمد بن ماجد في علم البحار.', 'الملك فلاح بن محسن جلب المانجو من الهند وزرعها في مقنيات.', 'استمر الغزو البرتغالي حتى قيام دولة اليعاربة 1624م.'],
 'تذكر مكونات المحكمة، وربط السلع بمناطقها على الخريطة، وتفسير انتصار البرتغاليين.', H,
 'كان للعُمانيين في عصر النباهنة محكمة منظمة فيها قاضٍ وكاتب ووكلاء، وكان فيهم علماء وشعراء وبحّار عظيم هو أحمد بن ماجد. وكانوا يتاجرون مع الهند والصين وإفريقيا، فطمع البرتغاليون في موانئهم وجاؤوا بسفنهم عام 1507م، فقاومهم العُمانيون لكن انقسامهم أضعفهم.',
 [('تتكون المحكمة من رئيس القضاة وقاضٍ وكاتب ...... ووكلاء', 'الحكم'), ('جلب العُمانيون الحرير من ......', 'الصين'), ('وصل البرتغاليون إلى جزر ...... عام 1507م', 'الحلانيات'), ('من أشهر ثورات العُمانيين على البرتغاليين ثورة عام ......م', '1521')],
 [('مؤلف النونية الكبرى (أحمد بن ماجد / الكيذاوي).', 'أحمد بن ماجد'), ('جلب العُمانيون العاج من (شرق إفريقيا / الهند).', 'شرق إفريقيا'), ('أثر الوجود البرتغالي على التجارة (ضعفها / ازدهارها).', 'ضعفها'), ('من أسباب انتصار البرتغاليين (الانقسامات الداخلية / الوحدة الوطنية).', 'الانقسامات الداخلية')],
 [('اذكر سببين لانتصار البرتغاليين.', 'الانقسامات الداخلية في عُمان، وضعف العُدة والعتاد.'), ('ما الذي أطمع البرتغاليين في الموانئ العُمانية؟', 'رواج التجارة فيها.'), ('اذكر سلعتين جلبهما العُمانيون من الهند.', 'التوابل وخشب الساج (أو الأرز).')],
 [('أحمد بن ماجد السعدي بحار عُماني ألّف النونية الكبرى.', True, 'من أبرز علماء العصر النبهاني في علم البحار.'), ('جلب العُمانيون الحرير من شرق إفريقيا.', False, 'جلبوه من الصين؛ أما شرق إفريقيا فمنها العاج والعنبر.'), ('تمكنت ثورة 1521م من إنهاء الوجود البرتغالي في عُمان.', False, 'وجهت ضربة موجعة لكنها لم تُنهِ الوجود البرتغالي.'), ('تحكّم البرتغاليون في السلع الصادرة والواردة.', True, 'بسيطرتهم التامة على الموانئ العُمانية.')],
 [('السيطرة البرتغالية على الموانئ', 'ضعف التجارة العُمانية', 'التحكم في الصادرات والواردات.'), ('رواج التجارة في الموانئ العُمانية', 'طمع البرتغاليين', 'الثروة تجذب الغزاة.')],
 ('الغزو البرتغالي للسواحل العُمانية', ['وصول البرتغاليين إلى جزر الحلانيات 1507م', 'السيطرة على مدن الساحل العُماني', 'ثورة العُمانيين 1521م', 'استمرار الغزو حتى قيام دولة اليعاربة 1624م']))

lesson(2453,
 'بمبايعة الإمام ناصر بن مرشد عام 1624م توحدت عُمان بالمفاوضات والحملات، ثم بدأ تحرير الساحل من البرتغاليين حتى تطهيره نهائيًا بتحرير مسقط ومطرح عام 1650م.',
 [('يعلّل عدّ دولة اليعاربة نقطة تحول', ['وحّدت البلاد وحمتها من الأطماع الخارجية.', 'انتعشت الحياة بتطور حضاري شمل جميع المجالات.']),
  ('يوضح جهود الإمام ناصر في التوحيد', ['استخدم المفاوضات والتواصل والحملات العسكرية.', 'المسار: الرستاق ← الداخلية ← الشرقية ← الظاهرة ← توام ← الباطنة.']),
  ('يتتبع طرد البرتغاليين', ['حرر الإمام ناصر معظم الساحل وحاصرهم في مسقط ومطرح، وعقد اتفاقية 1648م (الجزية، تسليم حصون، حرية التجارة).', 'حرر الإمام سلطان بن سيف مسقط ومطرح 1650م.', 'حُررت جلفار بقيادة الشيخ علي بن أحمد النزوي.'])],
 [('الجزية', 'مال يدفعه المغلوب للغالب'), ('جلفار', 'إحدى مدن شمال عُمان وحاضرة منطقة الصير'), ('توام', 'البريمي وما حولها'), ('الحامية', 'قوة عسكرية مقيمة لحماية مكان')],
 ['الإمام ناصر بن مرشد وُلد في قصرى بالرستاق وتوفي 1649م قبل تحرير مسقط.', 'الشيخ عبد الله بن محمد العنبوري واليًا على جلفار.', 'جعل الإمام سلطان بن سيف في ظفار حامية لتأمينها.'],
 'ترتيب مسار حملات التوحيد، والتمييز بين إنجازات الإمامين ناصر بن مرشد وسلطان بن سيف.', H,
 'بعد أن تفرقت عُمان في عصر النباهنة، جاء الإمام ناصر بن مرشد فجمعها من جديد؛ تحدث مع المدن وتفاوض، وأرسل الحملات من الرستاق حتى الباطنة. ثم بدأ يطرد البرتغاليين من الساحل، وجاء بعده الإمام سلطان بن سيف فحرر مسقط ومطرح عام 1650م وصارت عُمان حرة.',
 [('بويع الإمام ناصر بن مرشد عام ......م', '1624'), ('بدأ الإمام ناصر حملاته من ......', 'الرستاق'), ('عقد الإمام ناصر اتفاقية مع البرتغاليين عام ......م', '1648'), ('حُررت مسقط ومطرح عام ......م', '1650')],
 [('أكمل تحرير مسقط ومطرح الإمام (سلطان بن سيف / ناصر بن مرشد).', 'سلطان بن سيف'), ('حاضرة منطقة الصير (جلفار / صحار).', 'جلفار'), ('توام هي (البريمي وما حولها / الباطنة).', 'البريمي وما حولها'), ('قائد تحرير جلفار (علي بن أحمد النزوي / عبد الله العنبوري).', 'علي بن أحمد النزوي')],
 [('اذكر أسلوبين لتوحيد البلاد عند الإمام ناصر.', 'المفاوضات والتواصل مع المدن، والحملات العسكرية.'), ('اذكر بندين من اتفاقية 1648م.', 'دفع الجزية، وتسليم بعض الحصون (أو حرية التجارة).'), ('علّل: دولة اليعاربة نقطة تحول.', 'لتوحيدها البلاد وحمايتها من الأطماع الخارجية وانتعاش الحياة في عصرها.')],
 [('أتم الإمام ناصر بن مرشد تحرير مسقط ومطرح.', False, 'توفي قبل تحريرهما، وحررهما الإمام سلطان بن سيف 1650م.'), ('استخدم الإمام ناصر المفاوضات إلى جانب الحملات العسكرية.', True, 'أدرك أهمية الوحدة الوطنية فتواصل مع المدن.'), ('ألزمت اتفاقية 1648م البرتغاليين بدفع الجزية.', True, 'وتسليم بعض حصونهم وحرية التجارة.'), ('بدأت حملات التوحيد من الباطنة.', False, 'بدأت من الرستاق وما حولها وانتهت بالباطنة.')],
 [('الإمام ناصر بن مرشد', 'توحيد عُمان', 'المفاوضات والحملات العسكرية.'), ('الإمام سلطان بن سيف', 'تحرير مسقط ومطرح 1650م', 'تطهير البلاد نهائيًا من البرتغاليين.')],
 ('مسار حملات الإمام ناصر بن مرشد', ['الرستاق وما حولها', 'داخلية عُمان', 'الشرقية', 'الظاهرة', 'توام (البريمي)', 'الباطنة']))

lesson(2454,
 'لاحق العُمانيون البرتغاليين خارج بلادهم بأسطولهم، وطوّر اليعاربة تنظيمًا إداريًا محكمًا، وعمّ الرخاء الاقتصادي بالتجارة والوساطة وشق الأفلاج.',
 [('يحدد المدن التي واجه فيها العُمانيون البرتغاليين خارج عُمان', ['الخليج العربي وساحل الهند الغربي ومدخل البحر الأحمر وشرقي إفريقيا.', 'حملة الإمام سيف بن سلطان الأول إلى ممباسا 1698م، وحكم المزاريع لها.']),
  ('يوضح التنظيمات الإدارية', ['الإمام على رأسها، ثم الوالي الأكبر والولاة، والوكلاء، والقضاة، والمستشارون.', 'الوكلاء: بيت المال، الأفلاج، المساجد، الأيتام، الطرق، الغائب.']),
  ('يبرهن على الرخاء الاقتصادي', ['تأمين الطرق التجارية البحرية، وتصدير الخيل والتمور للهند واستيراد الملابس والأرز.', 'الوساطة التجارية وازدهار ميناء مسقط وأسواق إزكي ومنح.', 'شق الأفلاج (الخطمين، البزيلي، الصائغي) وإدخال الزعفران والبن.'])],
 [('الأسطول البحري', 'مجموعة السفن الحربية للدولة'), ('الوساطة التجارية', 'نقل السلع وتبادلها بين المناطق'), ('الوالي الأكبر', 'المشرف على الولاة في التنظيم الإداري اليعربي'), ('الفلج', 'قناة لنقل المياه للري والشرب')],
 ['فلج الخطمين في نزوى أُدرج في قائمة اليونسكو للتراث العالمي.', 'الشيخ عبد الله بن محمد بن غسان تولى منصب الوالي الأكبر في نزوى.', 'قال الإمام سلطان بن سيف الثاني: لأجعلن المسافر للحج يخرج من عُمان بلا زاد.'],
 'تذكر مكونات التنظيم الإداري، وربط المحاصيل والأفلاج بأماكنها، وتفسير الرخاء.', H,
 'بعد تحرير عُمان صار العُمانيون أقوياء في البحر، فلاحقوا البرتغاليين حتى إفريقيا والهند. ونظموا دولتهم: إمام في القمة، ووالٍ أكبر يتابع الولاة، ووكلاء يرعون الأموال والأفلاج والمساجد. وكثرت التجارة والزراعة فعاش الناس في رخاء.',
 [('حررت حملة الإمام سيف بن سلطان الأول مدينة ...... عام 1698م', 'ممباسا'), ('الأسرة التي حكمت ممباسا ......', 'المزاريع'), ('يقع فلج الخطمين في ولاية ......', 'نزوى'), ('من المحاصيل التي أدخلها اليعاربة الزعفران و......', 'البن')],
 [('صدّر العُمانيون إلى الهند (الخيل والتمور / الحرير والعاج).', 'الخيل والتمور'), ('فلج البزيلي في (ضنك / الرستاق).', 'ضنك'), ('يختص وكيل ...... بالمياه (الأفلاج / الأيتام).', 'الأفلاج'), ('من الأسواق المحلية في عصر اليعاربة (إزكي / زنجبار).', 'إزكي')],
 [('اذكر ثلاثة من الوكلاء.', 'وكيل بيت المال، وكيل الأفلاج، وكيل المساجد (أو الأيتام، الطرق، الغائب).'), ('علّل: توالت نداءات الاستغاثة على العُمانيين.', 'لذيوع صيتهم بعد انتصارهم على البرتغاليين، ومعاناة تلك المناطق من جور البرتغاليين.'), ('ما مظاهر الرخاء الاقتصادي في عصر اليعاربة؟', 'تأمين الطرق التجارية، والوساطة التجارية، وازدهار ميناء مسقط والأسواق، وشق الأفلاج.')],
 [('حكمت أسرة المزاريع ممباسا حتى نهاية دولة اليعاربة.', True, 'بعد أن جعل الإمام سيف بن سلطان الأول ناصر بن عبد الله المزروعي واليًا عليها.'), ('أدخل اليعاربة زراعة القرنفل إلى زنجبار.', False, 'أدخله السيد سعيد بن سلطان (عصر البوسعيد) عام 1842م؛ واليعاربة أدخلوا الزعفران والبن.'), ('يشرف الوالي الأكبر على الولاة.', True, 'حسب التنظيم الإداري في الشكل (12).'), ('اقتصر دور العُمانيين على طرد البرتغاليين من عُمان.', False, 'لاحقوهم في الخليج العربي وساحل الهند الغربي ومدخل البحر الأحمر وشرقي إفريقيا.')],
 [('فلج الخطمين', 'نزوى', 'من الأفلاج التي شقها اليعاربة.'), ('فلج الصائغي', 'الرستاق', 'من الأفلاج التي شقها اليعاربة.')],
 ('تحرير ممباسا', ['نداء استغاثة من ممباسا', 'إرسال الإمام سيف بن سلطان الأول حملة 1698م', 'تحرير المدينة من البرتغاليين', 'إقامة حامية عُمانية وتعيين ناصر بن عبد الله المزروعي واليًا']))

lesson(2455,
 'ازدهرت في عصر اليعاربة العمارة والعلم، وأقام اليعاربة علاقات ودية مع القوى الأوروبية، ثم ضعفت دولتهم بتنافس أفراد البيت اليعربي على الحكم.',
 [('يبرهن على ازدهار العمارة', ['تأسيس مدينة الحمراء وتطوير قرية الحزم ومسجد اليعاربة في نزوى.', 'حصون السنيسلة (صور) وبيت النعمان (بركاء) والحزم (الرستاق)، وقلعة نزوى «الشهباء».']),
  ('يعدّد المنجزات العلمية', ['الكتاتيب والمساجد والمجالس والمكتبات (جبرين، حصن الرستاق).', 'ظهور التعليم النظامي في مدرسة جبرين في عهد الإمام بلعرب بن سلطان.', 'علماء موسوعيون في الطب والفلك والشريعة والأدب والتاريخ.']),
  ('يعدّد الاتفاقيات ويستنتج أسباب النهاية', ['اتفاقية 1646م مع شركة الهند الشرقية البريطانية، ومشروع 1651م للهولنديين، والتجارة مع فرنسا.', 'النهاية: تنافس البيت اليعربي ومساندة رؤساء القبائل والحروب وأطماع الفرس.'])],
 [('الكتاتيب', 'مدارس تحفيظ القرآن الكريم'), ('التعليم النظامي', 'تعليم منظم ظهر لأول مرة في عُمان في مدرسة جبرين'), ('الشهباء', 'اسم قلعة نزوى تخليدًا لانتصار ديو'), ('شركة الهند الشرقية', 'شركة بريطانية تأسست 1600م وانتهت 1858م')],
 ['قلعة عراد في البحرين عُرفت باسم «سلطان بن سيف».', 'جواهر المنافع (الطب) للشيخ سليمان العوفي.', 'شمس الآفاق (الفلك) للشيخ خلفان السليماني.'],
 'ربط المعالم بأماكنها ومن بناها، وربط العلماء بمؤلفاتهم، واستنتاج أسباب النهاية.', H,
 'بنى اليعاربة قلاعًا وحصونًا قوية ما زلنا نزورها اليوم مثل قلعة نزوى وحصن جبرين، وفتحوا مدارس ومكتبات، وكان فيهم علماء يؤلفون في الطب والفلك. وصادقوا الدول الأوروبية بالاتفاقيات. لكن أفراد الأسرة تنازعوا على الحكم فضعفت الدولة وانتهت.',
 [('بنى الإمام سلطان بن سيف الأول قلعة ...... من غنائم ديو', 'نزوى'), ('ظهر التعليم النظامي في مدرسة ......', 'جبرين'), ('يقع حصن السنيسلة في ولاية ......', 'صور'), ('عقد الإمام ناصر اتفاقية مع شركة الهند الشرقية عام ......م', '1646')],
 [('مؤلف «شمس الآفاق» (خلفان السليماني / راشد الحبسي).', 'خلفان السليماني'), ('حصن بيت النعمان في (بركاء / الرستاق).', 'بركاء'), ('من أسباب نهاية اليعاربة (تنافس البيت اليعربي / الغزو البرتغالي).', 'تنافس البيت اليعربي'), ('مدرسة جبرين في عهد الإمام (بلعرب بن سلطان / ناصر بن مرشد).', 'بلعرب بن سلطان')],
 [('علّل تسمية قلعة نزوى بالشهباء.', 'تخليدًا لذكرى الانتصار العظيم على البرتغاليين في معركة ديو.'), ('اذكر مكتبتين من عصر اليعاربة.', 'مكتبة جبرين، ومكتبة حصن الرستاق.'), ('ما أسباب نهاية دولة اليعاربة؟', 'تنافس أفراد البيت اليعربي على الحكم بمساندة رؤساء القبائل، والحروب الطاحنة، وأطماع الفرس.')],
 [('قلعة نزوى بُنيت من غنائم معركة ديو.', True, 'بناها الإمام سلطان بن سيف الأول وسُمّيت الشهباء.'), ('أول تعليم نظامي في عُمان كان في عصر البوسعيد.', False, 'ظهر في عصر اليعاربة في مدرسة جبرين في عهد الإمام بلعرب بن سلطان.'), ('ديوان الحبسي من النتاج الأدبي في عصر اليعاربة.', True, 'للشاعر راشد بن خميس الحبسي.'), ('أقام اليعاربة علاقات عدائية مع كل القوى الأوروبية.', False, 'حرصوا على علاقات ودية وعقدوا اتفاقيات ومعاهدات.')],
 [('جواهر المنافع', 'الطب', 'للشيخ سليمان بن إبراهيم العوفي.'), ('قصص وأخبار جرت في عُمان', 'التاريخ', 'للشيخ محمد بن عامر المعولي.')],
 ('نهاية دولة اليعاربة', ['تنافس أفراد البيت اليعربي على الحكم', 'مساندة رؤساء القبائل لهم', 'دخول البلاد في حروب طاحنة', 'طمع الفرس في السيطرة على عُمان', 'قيام دولة البوسعيد']))

lesson(2456,
 'قامت دولة البوسعيد عام 1744م بتولي الإمام أحمد بن سعيد، فوحد البلاد وطرد الفرس، وحقق حكام البوسعيد منجزات سياسية وعسكرية بارزة بفضل الأسطول.',
 [('يتتبع نشأة الدولة', ['الإمام أحمد بن سعيد والٍ على صحار، وُلد في أدم وتوفي في الرستاق 1783م.', 'وحد البلاد وطرد الفرس واتخذ الرستاق عاصمة.']),
  ('يصمم مخططًا للمنجزات', ['أحمد بن سعيد: جيش قوي ثابت وأسطول بحري. سلطان بن أحمد: حرر البحرين من الفرس.', 'سعيد بن سلطان: إمبراطورية واسعة في آسيا وإفريقيا. عزان بن قيس: وحّد البلاد. فيصل بن تركي: علاقة متوازنة مع القوى الأوروبية.']),
  ('يوضح دور الأسطول ويدلّل على علاقات سعيد بن تيمور', ['تحرير البصرة من الحصار الفارسي 1775م، والسيادة على الخليج وبحر عُمان.', 'السلطان سعيد بن تيمور (حكم 1932م): اتفاقيات مع أمريكا والهند، وأول حاكم عربي يزور أمريكا.'])],
 [('الإمبراطورية العُمانية', 'الدولة العُمانية الممتدة بشقيها الآسيوي والإفريقي'), ('الأسطول', 'القوة البحرية الحربية للدولة'), ('الحصار', 'إحاطة مدينة بقوة عسكرية لمنع الدخول والخروج')],
 ['الحاكم العادل والعالم المخلص صمّام أمان للدول.', 'العلامة حبيب بن سالم أمبوسعيدي من أوائل المبايعين للإمام أحمد.', 'ربط السيد سعيد بن سلطان الشقين الآسيوي والإفريقي.'],
 'ربط كل حاكم بمنجزه، وترتيب أحداث الأسطول زمنيًا.', H,
 'كان أحمد بن سعيد واليًا على صحار حين اضطربت البلاد، فطرد الفرس ووحد عُمان عام 1744م وجعل الرستاق عاصمته. وصار للعُمانيين أسطول قوي حرر البصرة، ثم بنى السيد سعيد بن سلطان إمبراطورية تمتد من عُمان إلى إفريقيا.',
 [('بدأ عصر البوسعيد عام ......م', '1744'), ('كان الإمام أحمد بن سعيد واليًا على ......', 'صحار'), ('حرر الأسطول العُماني البصرة عام ......م', '1775'), ('تولى السلطان سعيد بن تيمور الحكم عام ......م', '1932')],
 [('حرر البحرين من الفرس (السيد سلطان بن أحمد / السيد سعيد بن سلطان).', 'السيد سلطان بن أحمد'), ('عاصمة الإمام أحمد بن سعيد (الرستاق / مسقط).', 'الرستاق'), ('أول حاكم عربي يزور أمريكا (سعيد بن تيمور / تيمور بن فيصل).', 'سعيد بن تيمور'), ('توفي الإمام أحمد بن سعيد عام (1783م / 1744م).', '1783م')],
 [('اذكر منجزين للأسطول في عصر البوسعيد.', 'تأمين السواحل وطرد الفرس، وتحرير البصرة 1775م.'), ('من أقام إمبراطورية في آسيا وإفريقيا؟', 'السيد سعيد بن سلطان.'), ('دلّل على اهتمام السلطان سعيد بن تيمور بالعلاقات الخارجية.', 'عقد اتفاقيات صداقة مع أمريكا والهند، وزار دولًا عديدة.')],
 [('اتخذ الإمام أحمد بن سعيد مسقط عاصمة له.', False, 'اتخذ الرستاق عاصمة له.'), ('حرر الأسطول العُماني البصرة من الحصار الفارسي.', True, 'في عام 1775م.'), ('السيد سعيد بن سلطان ربط الشق الآسيوي بالشق الإفريقي.', True, 'بواسطة الأسطول البحري.'), ('السلطان سعيد بن تيمور حكم في القرن الثامن عشر.', False, 'تولى الحكم عام 1932م (القرن العشرين).')],
 [('السيد سلطان بن أحمد', 'تحرير البحرين من الفرس', 'من منجزات دولة البوسعيد.'), ('السلطان فيصل بن تركي', 'علاقة متوازنة مع القوى الأوروبية المتنافسة', 'من منجزات دولة البوسعيد.')],
 ('من صحار إلى الإمبراطورية', ['تولي الإمام أحمد بن سعيد الحكم 1744م', 'طرد الفرس وتوحيد البلاد', 'تحرير البصرة 1775م', 'فرض السيادة على الخليج في عهد السيد سلطان بن أحمد', 'إمبراطورية السيد سعيد بن سلطان']))

lesson(2457,
 'تُوّجت منجزات البوسعيد بالنهضة الحديثة منذ 23 يوليو 1970م، وبعد وفاة السلطان قابوس انتقل الحكم بسلاسة إلى جلالة السلطان هيثم بن طارق في 11 يناير 2020م.',
 [('يعدّد شواهد النهضة', ['سلطنة عُمان دولة المؤسسات والقانون.', 'الاهتمام بقوات السلطان المسلحة وشرطة عُمان السلطانية تأهيلًا وتسليحًا.']),
  ('يبرهن على الاستقرار السياسي', ['توفي السلطان قابوس في 10 يناير 2020م، وتولى السلطان هيثم الحكم في 11 يناير 2020م.', 'رسالة السلطان قابوس لمجلس العائلة الحاكمة، وخطاب السلطان هيثم الأول بالسير على خطا الراحل.']),
  ('يصمم بطاقة تعريفية للسلطان هيثم', ['وُلد في مسقط 11 أكتوبر 1955م، ودرس في المدرسة السعيدية ثم أكسفورد (1979م).', 'وكيل الشؤون السياسية بالخارجية 1986م، ووزير التراث والثقافة (2002–2020م)، ورئيس لجنة رؤية عُمان 2040.'])],
 [('النهضة العُمانية الحديثة', 'مرحلة التطور الشامل منذ 23 يوليو 1970م'), ('دولة المؤسسات والقانون', 'دولة تُدار بمؤسسات منظمة ويسود فيها القانون'), ('الانتقال السلس للحكم', 'انتقال الحكم بهدوء وسرعة دون اضطراب')],
 ['مجلس العائلة الحاكمة يحدد من تنتقل إليه ولاية الحكم خلال ثلاثة أيام.', 'التخطيط المنظم والمدروس خطوة أساسية لتحقيق الهدف.', 'رؤية عُمان 2040 ترأس لجنتها الرئيسية جلالة السلطان هيثم.'],
 'حفظ التواريخ المفصلية (1970، 10 و11 يناير 2020) وبيانات السلطان هيثم.', H,
 'منذ عام 1970م بدأت عُمان نهضة كبيرة فصارت دولة مؤسسات وقانون. وعندما توفي السلطان قابوس -رحمه الله- في 10 يناير 2020م، تولى جلالة السلطان هيثم الحكم في اليوم التالي مباشرة، وهذا يدل على أن عُمان مستقرة وشعبها متماسك.',
 [('بدأت النهضة العُمانية الحديثة في 23 يوليو ......م', '1970'), ('تولى السلطان هيثم الحكم في ...... يناير 2020م', '11'), ('وُلد السلطان هيثم في مدينة ......', 'مسقط'), ('تولى السلطان هيثم وزارة التراث و......', 'الثقافة')],
 [('توفي السلطان قابوس في (10 يناير 2020م / 11 يناير 2020م).', '10 يناير 2020م'), ('ألقى السلطان هيثم خطابه الأول أمام (مجلس عُمان / مجلس الوزراء).', 'مجلس عُمان'), ('تخرج السلطان هيثم في جامعة (أكسفورد / القاهرة).', 'أكسفورد'), ('رأس السلطان هيثم لجنة (رؤية عُمان 2040 / النظام الأساسي).', 'رؤية عُمان 2040')],
 [('اذكر شاهدين للنهضة الحديثة.', 'دولة المؤسسات والقانون، والاهتمام بالقوات المسلحة والشرطة.'), ('ما دلالة سلاسة انتقال الحكم؟', 'عراقة عُمان وتماسك شعبها وحكمة حكامها.'), ('بمَ عاهد السلطان هيثم شعبه في خطابه الأول؟', 'بالسير على خطا السلطان الراحل.')],
 [('تولى السلطان هيثم الحكم بعد وفاة السلطان قابوس بيوم واحد.', True, 'توفي السلطان قابوس 10 يناير 2020م وتولى السلطان هيثم الحكم 11 يناير 2020م.'), ('بدأت النهضة الحديثة عام 1932م.', False, 'بدأت في 23 يوليو 1970م؛ وعام 1932م تولى فيه السلطان سعيد بن تيمور الحكم.'), ('تولى السلطان هيثم وزارة التراث والثقافة.', True, 'في الفترة (2002م – 2020م).'), ('من شواهد النهضة الاهتمام بشرطة عُمان السلطانية.', True, 'بالتأهيل والتدريب وتزويدها بالمعدات المتطورة.')],
 [('23 يوليو 1970م', 'بداية النهضة العُمانية الحديثة', 'في عهد السلطان قابوس بن سعيد.'), ('11 يناير 2020م', 'تولي السلطان هيثم بن طارق الحكم', 'انتقال سلس للحكم.')],
 ('سيرة جلالة السلطان هيثم بن طارق', ['المولد في مسقط 1955م', 'التخرج في أكسفورد 1979م', 'وكيل الشؤون السياسية 1986م', 'وزير التراث والثقافة 2002م', 'تولي الحكم 11 يناير 2020م']))

lesson(2458,
 'طوّر حكام البوسعيد النظام الإداري، وازدهر الاقتصاد بالتجارة والوساطة والزراعة والصناعة، واكتسب ميناء زنجبار شهرة عالمية.',
 [('يعدّد مكونات التنظيم الإداري في عهد الإمام أحمد بن سعيد', ['التشريعية: العلماء، الوجهاء والأعيان.', 'التنفيذية: الولاة، بيت المال، جباة الضرائب، الشرطة، الحرس، الجيش، الأسطول.', 'القضائية: قاضي القضاة، القضاة.']),
  ('يصنّف السلع التجارية', ['محلية: التمور والأسماك واللبان والعسل والصمغ.', 'مستوردة: البن من اليمن، والملح من فارس، والعاج من شرقي إفريقيا.']),
  ('يبرهن على ازدهار الزراعة والصناعة', ['القرنفل في زنجبار 1842م جعلها أكبر مصدر له في العالم.', 'صناعة السفن في مطرح ومسقط وصور.', 'زارت ميناء زنجبار 41 سفينة أجنبية (1832–1834م).'])],
 [('السلطة التشريعية', 'جهة سن الأنظمة: العلماء والوجهاء والأعيان'), ('السلطة التنفيذية', 'جهة تنفيذ الأنظمة وإدارة الدولة'), ('الوساطة التجارية', 'توزيع السلع المحلية والمستوردة ونقلها بين المناطق'), ('القرنفل', 'محصول أدخله السيد سعيد بن سلطان إلى زنجبار')],
 ['ما يعادل خمسة أثمان تجارة الخليج مرّ بميناء مسقط أواخر القرن 18م.', 'الصناعات الحرفية موروث حضاري ومكوّن اقتصادي.', 'من أسباب الوساطة: الموقع الاستراتيجي والخبرة الملاحية.'],
 'تصنيف مكونات السلطات الثلاث، وتصنيف السلع محلية ومستوردة.', H,
 'نظّم الإمام أحمد بن سعيد دولته في ثلاث سلطات: علماء ووجهاء يشيرون، وولاة وجيش ينفذون، وقضاة يحكمون. وكان التجار العُمانيون يبيعون التمور واللبان، ويحضرون البن والملح والعاج، وأصبحت زنجبار أشهر بلد في العالم بالقرنفل.',
 [('من السلطة التشريعية: العلماء والوجهاء و......', 'الأعيان'), ('استورد العُمانيون الملح من بلاد ......', 'فارس'), ('أُدخل القرنفل إلى زنجبار عام ......م', '1842'), ('زارت ميناء زنجبار ...... سفينة أجنبية (1832–1834م)', '41')],
 [('جباة الضرائب من السلطة (التنفيذية / القضائية).', 'التنفيذية'), ('اللبان سلعة (محلية / مستوردة).', 'محلية'), ('البن مستورد من (اليمن / الهند).', 'اليمن'), ('من موانئ صناعة السفن (صور / باتي).', 'صور')],
 [('اذكر مكونات السلطة القضائية.', 'قاضي القضاة، والقضاة.'), ('علّل: أصبحت زنجبار أكبر مصدر للقرنفل.', 'لإدخال السيد سعيد بن سلطان زراعته عام 1842م ورواج تجارته.'), ('اذكر سببين للوساطة التجارية العُمانية.', 'الموقع الاستراتيجي، والخبرة الملاحية (أو ازدهار الموانئ، البراعة في صناعة السفن).')],
 [('الشرطة من مكونات السلطة التنفيذية.', True, 'مع الولاة وبيت المال وجباة الضرائب والحرس والجيش والأسطول.'), ('القرنفل من السلع المستوردة من اليمن.', False, 'البن هو المستورد من اليمن؛ والقرنفل زُرع في زنجبار.'), ('العاج سلعة استوردها العُمانيون من شرقي إفريقيا.', True, 'كما ورد في الكتاب ص 42.'), ('العلماء جزء من السلطة القضائية.', False, 'العلماء من السلطة التشريعية؛ القضائية: قاضي القضاة والقضاة.')],
 [('البن', 'اليمن', 'سلعة مستوردة.'), ('الملح', 'بلاد فارس', 'سلعة مستوردة.')],
 ('رحلة القرنفل', ['إدخال السيد سعيد بن سلطان القرنفل إلى زنجبار 1842م', 'رواج تجارته', 'صار من الموارد الرئيسية لخزينة الدولة', 'أصبحت زنجبار أكبر مصدر للقرنفل في العالم']))

lesson(2459,
 'شمل اهتمام البوسعيد العمارة والتعليم والعلم، واستمرت عُمان في علاقاتها الخارجية بالمعاهدات، حتى صارت في عهد السلطان قابوس مرسى السلام والأمان.',
 [('يرسم جدولًا للمنجزات العمرانية', ['حصن المنصور (الإمام سعيد بن أحمد – الرستاق)، قلعة الراوية (السيد سلطان بن أحمد – مسقط)، حصن الفليج (بركاء).', 'حصن الخندق (السيد سعيد بن سلطان – البريمي)، بيت العجائب والمرهوبي (السلطان برغش – زنجبار).']),
  ('يتتبع تطور التعليم ويذكر العلماء', ['مدرسة بيت القرن بالرستاق ← المدرسة السلطانية الأولى (تيمور بن فيصل) ← انتشار المدارس.', 'مهنا بن خلفان: تهذيب الأثر. ناصر بن جاعد: موسوعة العلم المبين. أبو الصوفي: ديوان طُبع في أوساكا. أحمد الخليلي: برهان الحق.']),
  ('يبرهن على تعزيز العلاقات الخارجية', ['معاهدة السيد سعيد بن سلطان مع أمريكا 1833م، واتفاقية السيد سلطان بن أحمد مع بريطانيا 1800م.', 'سياسة السلام والحوار وعدم التدخل في عهد السلطان قابوس، وسار عليها السلطان هيثم.'])],
 [('الوقف', 'تخصيص مال أو عقار لمنفعة عامة كالتعليم'), ('الموسوعة', 'مؤلف شامل في فروع المعرفة'), ('المعاهدة', 'اتفاق رسمي بين دولتين'), ('سياسة السلام', 'نهج الحوار وحل الخلافات بالطرق السلمية')],
 ['سفينة «سلطانة» أبحرت إلى لندن 1842م.', 'الشيخ أحمد بن حمد الخليلي مفتي عام السلطنة منذ 1975م.', 'العمارة مرآة لحضارة البلد وانعكاس لهويته.'],
 'ربط كل معلم بحاكمه ومكانه، وترتيب مراحل التعليم، وأمثلة المعاهدات.', H,
 'بنى حكام البوسعيد حصونًا وقصورًا كحصن المنصور وبيت العجائب. وتطور التعليم من حلقات القرآن إلى المدارس النظامية حتى صارت المدارس في كل قرية. وصادقت عُمان أمريكا وبريطانيا، وفي عهد السلطان قابوس صارت صديقة لكل العالم.',
 [('بنى الإمام سعيد بن أحمد حصن ...... في الرستاق', 'المنصور'), ('بُني حصن الخندق في ......', 'البريمي'), ('عقد السيد سعيد بن سلطان معاهدة مع أمريكا عام ......م', '1833'), ('مؤلف «برهان الحق» الشيخ أحمد بن حمد ......', 'الخليلي')],
 [('بيت العجائب في (زنجبار / مسقط).', 'زنجبار'), ('بدأ التعليم النظامي في عهد (تيمور بن فيصل / أحمد بن سعيد).', 'تيمور بن فيصل'), ('طُبع ديوان أبي الصوفي في (اليابان / مصر).', 'اليابان'), ('اتفاقية 1800م كانت مع (بريطانيا / فرنسا).', 'بريطانيا')],
 [('رتّب مراحل تطور التعليم في عصر البوسعيد.', 'مدرسة بيت القرن ← المدرسة السلطانية الأولى ← انتشار المدارس.'), ('اذكر أساسين للسياسة الخارجية في عهد السلطان قابوس.', 'السلم والحوار، وعدم التدخل في شؤون الغير.'), ('ما نتيجة سياسة السلام العُمانية؟', 'محبة العالم لسلطنة عُمان وأصبحت مرسى السلام والأمان.')],
 [('معاهدة 1833م من أقدم العلاقات السياسية العربية الأمريكية.', True, 'عقدها السيد سعيد بن سلطان مع الولايات المتحدة.'), ('حصن الفليج بُني في عهد السيد سعيد بن سلطان.', False, 'بُني في عهد السيد سلطان بن أحمد في بركاء.'), ('مدرسة بيت القرن من حلقات تحفيظ القرآن.', True, 'بالرستاق في عهد الإمام أحمد بن سعيد.'), ('سمحت اتفاقية 1800م لبريطانيا بتعيين وكيل سياسي في مسقط.', True, 'عقدها السيد سلطان بن أحمد مع السير جون مالكولم.')],
 [('حصن المنصور', 'الرستاق', 'بناه الإمام سعيد بن أحمد.'), ('قلعة الراوية', 'مسقط', 'بناها السيد سلطان بن أحمد.')],
 ('تطور التعليم في عصر البوسعيد', ['حلقات تحفيظ القرآن (مدرسة بيت القرن)', 'التعليم النظامي في المدرسة السلطانية الأولى', 'انتشار المدارس في كل مدن عُمان وقراها']))

lesson(2460,
 'البيئة هي الوسط الذي تعيش فيه الكائنات الحية تتأثر به وتؤثر فيه، وتنقسم إلى طبيعية ومشيّدة، والتنوع الأحيائي عامل مهم لتحقيق التوازن البيئي.',
 [('يعرّف البيئة ويصنّف مكوناتها', ['الطبيعية: الكائنات الحية وما يحيط بها من ماء وهواء وموارد.', 'المشيّدة: ما أنشأه الإنسان كالمباني والمزارع والأنشطة.']),
  ('يوضح التفاعل بين البيئتين', ['تفاعل إيجابي يسهم في الاستدامة.', 'تفاعل سلبي يضر بالبيئة وينتج عنه مشكلات.']),
  ('يعطي أمثلة لأهمية التنوع الأحيائي', ['الطبي: عقاقير من أصل نباتي أو حيواني. الزراعي: المكافحة الحيوية.', 'البيئي: المحافظة على مكونات الهواء. الصناعي: مواد خام حيوانية أو نباتية.'])],
 [('البيئة', 'الوسط الذي تعيش فيه الكائنات الحية تتأثر به وتؤثر فيه'), ('البيئة المشيّدة', 'ما أنشأه الإنسان نتيجة تفاعله واستثماره لموارد بيئته'), ('التنوع الأحيائي', 'تعدد أنواع الكائنات الحية وكثرتها وتباينها في النظم البرية والمائية والجوية')],
 ['بيئتنا ليست ميراثًا عن آبائنا بل استعارة من أبنائنا.', 'المحافظة على التنوع الأحيائي مسؤولية عالمية مشتركة.', 'سعت الدول لحماية البيئة بالتشريعات والمنظمات.'],
 'التمييز بين البيئة الطبيعية والمشيّدة، وأمثلة أهمية التنوع الأحيائي.', E,
 'البيئة هي كل ما حولنا: الشجر والماء والهواء والحيوانات (بيئة طبيعية)، والبيوت والمزارع التي بناها الإنسان (بيئة مشيّدة). وكلما تنوعت الكائنات الحية كان ذلك أفضل لنا؛ فمنها نصنع الأدوية ونحمي المزروعات.',
 [('البيئة التي أنشأها الإنسان تسمى البيئة ......', 'المشيّدة'), ('من أمثلة البيئة المشيّدة المباني و......', 'المزارع'), ('المكافحة الحيوية مثال على أهمية التنوع الأحيائي في المجال ......', 'الزراعي'), ('تعدد أنواع الكائنات الحية وكثرتها يسمى التنوع ......', 'الأحيائي')],
 [('الماء والهواء من البيئة (الطبيعية / المشيّدة).', 'الطبيعية'), ('العقاقير من أصل نباتي مثال على المجال (الطبي / الصناعي).', 'الطبي'), ('التفاعل الذي يسهم في الاستدامة (إيجابي / سلبي).', 'إيجابي'), ('المحافظة على التنوع الأحيائي مسؤولية (عالمية مشتركة / فردية).', 'عالمية مشتركة')],
 [('عرّف البيئة.', 'الوسط أو المجال المكاني الذي تعيش فيه الكائنات الحية، تتأثر به وتؤثر فيه.'), ('اذكر نوعي التفاعل بين البيئتين.', 'إيجابي يسهم في الاستدامة، وسلبي يضر بالبيئة.'), ('أعط مثالًا لأهمية التنوع الأحيائي في المجال البيئي.', 'المحافظة على مكونات الهواء.')],
 [('المباني من مكونات البيئة الطبيعية.', False, 'المباني من البيئة المشيّدة التي أنشأها الإنسان.'), ('التفاعل بين البيئتين قد يكون إيجابيًا أو سلبيًا.', True, 'الإيجابي يسهم في الاستدامة والسلبي يضر بالبيئة.'), ('من أهمية التنوع الأحيائي المكافحة الحيوية للآفات.', True, 'في المجال الزراعي.'), ('التنوع الأحيائي يقتصر على النظم البرية.', False, 'يشمل النظم البيئية البرية والمائية والجوية.')],
 [('البيئة الطبيعية', 'الكائنات الحية والماء والهواء', 'موارد لم يصنعها الإنسان.'), ('البيئة المشيّدة', 'المباني والمزارع والأنشطة', 'من صنع الإنسان.')],
 ('من الحاجة إلى الحماية', ['ارتباط الإنسان بالبيئة وأخذه قدر حاجته', 'تعدد متطلبات الإنسان مع تطور الحياة', 'استنزاف البيئة وتأثر التنوع الأحيائي', 'إصدار التشريعات وإنشاء المنظمات لحماية البيئة']))

lesson(2461,
 'تعبّر الرؤية العُمانية عن أن البيئة المحلية جزء من البيئة العالمية، فعقدت سلطنة عُمان المؤتمرات وشاركت فيها وصادقت على الاتفاقيات، وخصصت جائزة عالمية لصون البيئة.',
 [('يصمم خريطة مفاهيم لجهود عُمان العالمية', ['عقد مؤتمرات: الحياة تحت الماء (صلالة 2017م)، مؤتمر عُمان للبيئة (جلف إكو 2013م).', 'المشاركة: تغير المناخ بألمانيا 2017م، إدارة المخلفات الخطرة بجنيف 2015م.', 'التعاون: المنظمة الإقليمية لحماية البيئة البحرية، برنامج الأمم المتحدة للبيئة. المصادقة: التنوع الأحيائي، فيينا لحماية الأوزون.']),
  ('يرسم مخططًا لجائزة اليونسكو', ['أُعلنت 1989م في مقر اليونسكو، وهي الأولى من نوعها.', 'تُمنح كل عامين للأفراد والمنظمات والمؤسسات، شهادة تقديرية ومنحة مالية.']),
  ('يحلّل الخطاب السامي', ['التوعية بقضايا البيئة.', 'تعبئة التضامن الدولي لتخفيف الأضرار الناشئة عن المخاطر الطبيعية.'])],
 [('الرؤية العُمانية للبيئة', 'إدراك أن البيئة المحلية جزء لا يتجزأ من البيئة العالمية'), ('جائزة اليونسكو – السلطان قابوس', 'جائزة عالمية لصون البيئة تُمنح كل عامين منذ 1989م'), ('المصادقة على الاتفاقية', 'الموافقة الرسمية على الالتزام بها')],
 ['أطلقت دول المحيط الهندي اسم سلطنة عُمان على برنامج حماية السلاحف 2006م.', 'حصد صندوق أشوكا ترست بالهند الجائزة لعام 2019م.', 'منتدى عُمان البيئي من أبرز الفعاليات البيئية.'],
 'تصنيف جهود عُمان العالمية في فئاتها الأربع، وبيانات جائزة اليونسكو.', E,
 'عُمان تعرف أن البيئة واحدة في كل العالم، فإذا تلوث البحر في مكان وصل الضرر إلى غيره. لذلك تستضيف المؤتمرات البيئية وتشارك فيها وتوقّع الاتفاقيات، وخصص السلطان قابوس -رحمه الله- جائزة عالمية تمنحها اليونسكو كل عامين لمن يحمي البيئة.',
 [('أُعلنت جائزة اليونسكو – السلطان قابوس عام ......م', '1989'), ('تُمنح الجائزة كل ......', 'عامين'), ('عُقد مؤتمر الحياة تحت الماء في مدينة ......', 'صلالة'), ('صادقت عُمان على اتفاقية فيينا لحماية طبقة ......', 'الأوزون')],
 [('مؤتمر تغير المناخ 2017م كان في (ألمانيا / جنيف).', 'ألمانيا'), ('جلف إكو 2013م من (عقد المؤتمرات / المصادقة على الاتفاقيات).', 'عقد المؤتمرات'), ('تتكون الجائزة من شهادة تقديرية و(منحة مالية / ميدالية ذهبية).', 'منحة مالية'), ('حصد الجائزة 2019م صندوق أشوكا ترست في (الهند / مصر).', 'الهند')],
 [('اذكر فئتين من جهود عُمان لحماية البيئة العالمية.', 'عقد المؤتمرات الدولية، والمصادقة على الاتفاقيات (أو المشاركة في المؤتمرات، التعاون مع المنظمات).'), ('لماذا أُطلق اسم عُمان على برنامج حماية السلاحف؟', 'تقديرًا لمكانة سلطنة عُمان في العمل البيئي.'), ('لمن تُمنح جائزة اليونسكو – السلطان قابوس؟', 'للأفراد أو المنظمات أو المؤسسات ذات الإنجاز البارز في صون البيئة.')],
 [('تُمنح جائزة اليونسكو – السلطان قابوس سنويًا.', False, 'تُمنح كل عامين.'), ('عقدت عُمان مؤتمر الحياة تحت الماء في صلالة.', True, 'عام 2017م.'), ('صادقت عُمان على اتفاقية التنوع الأحيائي.', True, 'ضمن المصادقة على الاتفاقيات الإقليمية والدولية.'), ('البيئة المحلية منفصلة عن البيئة العالمية.', False, 'الرؤية العُمانية تعدّها جزءًا لا يتجزأ منها.')],
 [('مؤتمر تغير المناخ بألمانيا 2017م', 'المشاركة في المؤتمرات', 'من جهود عُمان العالمية.'), ('اتفاقية فيينا لحماية الأوزون', 'المصادقة على الاتفاقيات', 'من جهود عُمان العالمية.')],
 ('جائزة اليونسكو – السلطان قابوس', ['زيارة السلطان قابوس لمقر اليونسكو 1989م', 'إعلان الجائزة الأولى من نوعها', 'منحها كل عامين للمهتمين بصون البيئة', 'تقديمها شهادة تقديرية ومنحة مالية']))

lesson(2462,
 'تتنوع بيئات عُمان الطبيعية بتعدد مظاهر السطح والموقع الجغرافي والفلكي وتنوع المناخ، ولتنوعها الأحيائي أهمية اقتصادية كبيرة منها السياحة البيئية.',
 [('يستنتج عوامل تنوع البيئات', ['تعدد مظاهر السطح: الجبال والسهول والواحات والهضاب.', 'الموقع الجغرافي والفلكي وامتداد السواحل الطويلة وتنوع المناخ.']),
  ('يوضح الأهمية الاقتصادية للتنوع الأحيائي', ['تعدد الأنشطة الاقتصادية المرتبطة بالثروات الحيوانية والمائية والنباتية.', 'تعدد المهن والحرف وأنماط الحياة.']),
  ('يستعرض السياحة البيئية', ['مواقع ذات مناظر طبيعية وحياة فطرية متنوعة.', 'السواحل والأخوار والجزر والكهوف.'])],
 [('الحياة الفطرية', 'الكائنات الحية التي تعيش في بيئتها الطبيعية'), ('السياحة البيئية', 'سياحة لمحبي الطبيعة والمغامرات ومراقبة الحيوانات'), ('مظاهر السطح', 'أشكال التضاريس كالجبال والسهول والهضاب')],
 ['أدركت عُمان منذ بداية النهضة أهمية حماية البيئة للأجيال القادمة.', 'المحافظة على المواقع السياحية البيئية مسؤولية مشتركة.', 'التنوع الأحيائي ثروة وطنية.'],
 'ربط عوامل التنوع البيئي بأمثلة، واستنتاج الأهمية الاقتصادية.', E,
 'في عُمان جبال وسهول وصحارٍ وسواحل طويلة، ولهذا تعيش فيها حيوانات ونباتات كثيرة ومختلفة. وهذا التنوع يفيدنا: نصطاد ونزرع ونرعى، ويأتي السياح لرؤية الطبيعة الجميلة في الكهوف والأخوار والجزر.',
 [('من عوامل تنوع البيئات تعدد مظاهر ......', 'السطح'), ('من مواقع السياحة البيئية الكهوف و......', 'الأخوار'), ('التنوع الأحيائي في عُمان ثروة ......', 'وطنية'), ('تنوع الثروات الطبيعية أدى إلى تعدد الأنشطة ......', 'الاقتصادية')],
 [('من عوامل تنوع البيئات (الموقع الفلكي / الانفجار السكاني).', 'الموقع الفلكي'), ('السياحة البيئية تناسب محبي (الطبيعة / التسوق).', 'الطبيعة'), ('امتداد عُمان على سواحل (طويلة / قصيرة).', 'طويلة'), ('تعدد المهن والحرف نتج عن الاعتماد على (البيئة الطبيعية / الاستيراد).', 'البيئة الطبيعية')],
 [('اذكر عاملين لتنوع البيئات العُمانية.', 'تعدد مظاهر السطح، والموقع الجغرافي والفلكي (أو تنوع المناخ).'), ('ما الأهمية الاقتصادية للتنوع الأحيائي؟', 'تعدد الأنشطة الاقتصادية، وامتلاك مقومات السياحة البيئية.'), ('اذكر موقعين للسياحة البيئية.', 'السواحل والأخوار (أو الجزر والكهوف).')],
 [('يرتبط تنوع البيئات العُمانية بالموقع الفلكي.', True, 'إلى جانب الموقع الجغرافي ومظاهر السطح وتنوع المناخ.'), ('السياحة البيئية تقوم على المصانع والموانئ.', False, 'تقوم على المناظر الطبيعية والحياة الفطرية كالسواحل والكهوف.'), ('التنوع الأحيائي ذو أهمية اقتصادية كبيرة.', True, 'أدى إلى تعدد الأنشطة الاقتصادية.'), ('عُمان بيئة واحدة متشابهة.', False, 'تتنوع بيئاتها بين جبال وسهول وواحات وهضاب وسواحل.')],
 [('تعدد مظاهر السطح', 'تنوع البيئات الطبيعية', 'جبال وسهول وواحات وهضاب.'), ('التنوع الأحيائي', 'السياحة البيئية', 'تنوع الحياة الفطرية يجذب السياح.')],
 ('من التنوع إلى الاقتصاد', ['تنوع البيئات الطبيعية', 'تنوع الحياة الفطرية (التنوع الأحيائي)', 'تعدد الثروات الطبيعية', 'تعدد الأنشطة الاقتصادية والسياحة البيئية']))

lesson(2463,
 'وازنت سلطنة عُمان بين التنمية وحماية البيئة بالخطط الخمسية ورؤية عُمان 2040 والنظام الأساسي، وأصدرت تشريعات لحماية الأرض والمياه والبحر والهواء.',
 [('يدلّل على التوازن بين التنمية والبيئة', ['الخطط الخمسية منذ 1976م ربطت التنمية بالمحافظة على البيئة.', 'رؤية عُمان 2040 ركزت على التنمية المستدامة، والمادة (12) من النظام الأساسي.']),
  ('يعطي أمثلة للتشريعات', ['قانون حماية البيئة ومكافحة التلوث 1982م المعدل بالمرسوم (114/2001).', 'المرسوم (115/2001) لحماية مصادر مياه الشرب من التلوث.']),
  ('يحدد المنطقة البحرية الخاصة ومحطات الهواء', ['من رأس الحد إلى الحدود الجنوبية بنحو 200 ميل بحري بالتعاون مع IMO.', 'محطات قياس الهواء: قرب ميناء الفحل (مسقط)، وريسوت (صلالة)، وميناء صحار.'])],
 [('التنمية المستدامة', 'تنمية تلبي حاجات الحاضر دون الإضرار بموارد الأجيال القادمة'), ('المنطقة البحرية الخاصة', 'منطقة بحرية محمية من رأس الحد إلى الحدود الجنوبية'), ('التصريح البيئي', 'موافقة تُشترط لبعض المشاريع لضمان عدم إضرارها بالبيئة')],
 ['خطاب السلطان قابوس في قمة الأرض 1992م دعا للتعامل العقلاني مع البيئة.', 'المنظمة البحرية الدولية (IMO).', 'المادة (21) من قانون حماية البيئة تُطبّق في البيئة المدرسية.'],
 'ربط كل تشريع برقمه وهدفه، وتحديد المواقع على الخريطة.', E,
 'أرادت عُمان أن تبني المصانع والطرق دون أن تفسد البيئة، فوضعت خططًا وقوانين تحمي الأرض والماء والبحر والهواء. فمثلًا: منطقة بحرية خاصة محمية من التلوث، ومحطات تقيس نظافة الهواء قرب الموانئ.',
 [('صدر قانون حماية البيئة ومكافحة التلوث عام ......م', '1982'), ('المرسوم (115/2001) لحماية مصادر مياه ......', 'الشرب'), ('تمتد المنطقة البحرية الخاصة من رأس ......', 'الحد'), ('توجد محطة لقياس جودة الهواء قرب منطقة ...... الصناعية في صلالة', 'ريسوت')],
 [('تعديل قانون حماية البيئة بالمرسوم (114/2001 / 6/2003).', '114/2001'), ('صنّفت عُمان المنطقة البحرية الخاصة بالتعاون مع (IMO / اليونسكو).', 'IMO'), ('تنص المادة (12) من النظام الأساسي على (حماية البيئة / حرية التجارة).', 'حماية البيئة'), ('بدأت الخطط الخمسية عام (1976م / 1996م).', '1976م')],
 [('اذكر تشريعين بيئيين في عُمان.', 'قانون حماية البيئة ومكافحة التلوث، والمرسوم (115/2001) لحماية مياه الشرب.'), ('ما هدف المنطقة البحرية الخاصة؟', 'حماية البيئة البحرية العُمانية من التلوث.'), ('علّل: إنشاء محطات قياس جودة الهواء.', 'لرصد مستويات التلوث والحرص على عدم تجاوزها المستويات المسموحة.')],
 [('تمتد المنطقة البحرية الخاصة من مسندم إلى رأس الحد.', False, 'تمتد من رأس الحد إلى الحدود العُمانية الجنوبية.'), ('صدر قانون حماية البيئة ومكافحة التلوث عام 1982م.', True, 'وعُدّل بالمرسوم (114/2001).'), ('توجد محطة لقياس الهواء قرب ميناء الفحل.', True, 'في محافظة مسقط.'), ('الخطط الخمسية تجاهلت البيئة.', False, 'تضمنت منذ 1976م مبدأ ربط التنمية بالمحافظة على البيئة.')],
 [('المرسوم (115/2001)', 'حماية مصادر مياه الشرب', 'من التلوث.'), ('المرسوم (114/2001)', 'تعديل قانون حماية البيئة ومكافحة التلوث', 'تجنب الإضرار بالبيئة.')],
 ('مسار حماية البيئة العُمانية', ['الخطط الخمسية منذ 1976م', 'قانون حماية البيئة 1982م', 'المادة (12) من النظام الأساسي', 'رؤية عُمان 2040']))

lesson(2464,
 'مرّ العمل البيئي في عُمان بمراحل تنظيمية؛ فهي أول دولة عربية تخصص وزارة للبيئة (1984م)، وتعمل المؤسسات الحكومية مع الخاصة والأهلية وأفراد المجتمع.',
 [('يرسم خريطة مفاهيم لنوعي المؤسسات', ['الحكومية: الدراسات والمشاريع البيئية وإصدار القوانين والقرارات.', 'الخاصة والأهلية: دعم جهود الحكومة بحملات تنظيف الشواطئ والمسابقات وحملات التوعية.']),
  ('يستنتج المقصود بالاقتصاد الأخضر', ['منظومة اقتصادية تحقق التنمية مع المحافظة على البيئة.', 'مكتب مساندة الاقتصاد الأخضر بالتعاون مع الإسكوا.']),
  ('يناقش مبادرة أشجار', ['تشرف عليها هيئة البيئة.', 'تهدف لزراعة الأشجار ومكافحة التصحر بمشاركة المجتمع.'])],
 [('الاقتصاد الأخضر', 'منظومة اقتصادية تحقق التنمية مع حماية البيئة والاستغلال الأمثل للموارد'), ('الإسكوا', 'اللجنة الاقتصادية والاجتماعية لغربي آسيا'), ('المؤسسات الأهلية', 'جمعيات ومؤسسات مجتمعية غير حكومية')],
 ['التكاتف الوطني أساس بيئة عُمانية مستدامة.', 'من أمثلة المشاريع الخضراء: الطاقة المتجددة والعمارة الخضراء وتدوير الموارد.', 'هيئة البيئة تشرف على مبادرة أشجار.'],
 'التمييز بين أدوار المؤسسات الحكومية والأهلية، ومفهوم الاقتصاد الأخضر.', E,
 'حماية البيئة عمل جماعي: الحكومة تضع القوانين وتجري الدراسات، والجمعيات والشركات تنظف الشواطئ وتوعي الناس. وعُمان أول دولة عربية أنشأت وزارة للبيئة. والاقتصاد الأخضر يعني أن نربح ونتقدم دون أن نلوث الطبيعة.',
 [('عُمان أول دولة عربية تخصص وزارة للبيئة عام ......م', '1984'), ('تشرف هيئة البيئة على مبادرة ......', 'أشجار'), ('دُشن مكتب مساندة الاقتصاد ...... بالتعاون مع الإسكوا', 'الأخضر'), ('من أنشطة المؤسسات الأهلية حملات تنظيف ......', 'الشواطئ')],
 [('إصدار القوانين البيئية مهمة المؤسسات (الحكومية / الأهلية).', 'الحكومية'), ('الطاقة الشمسية مثال على مشروع (أخضر / ملوِّث).', 'أخضر'), ('الإسكوا لجنة تابعة لـ (الأمم المتحدة / اليونسكو).', 'الأمم المتحدة'), ('المسابقات البيئية من أنشطة المؤسسات (الأهلية / القضائية).', 'الأهلية')],
 [('عرّف الاقتصاد الأخضر.', 'منظومة اقتصادية تحقق التنمية مع المحافظة على البيئة والاستغلال الأمثل للموارد.'), ('اذكر نشاطين للمؤسسات الأهلية.', 'حملات تنظيف الشواطئ، والمسابقات (أو حملات التوعية).'), ('دلّل على الاهتمام المبكر بالمؤسسات البيئية.', 'عُمان أول دولة عربية تخصص وزارة معنية بالبيئة عام 1984م.')],
 [('عُمان أول دولة عربية تخصص وزارة للبيئة.', True, 'عام 1984م.'), ('حماية البيئة مسؤولية الحكومة وحدها.', False, 'تعمل المؤسسات الحكومية جنبًا إلى جنب مع الخاصة والأهلية وأفراد المجتمع.'), ('الاقتصاد الأخضر يحقق التنمية مع حماية البيئة.', True, 'من خلال الاستغلال الأمثل للموارد الطبيعية.'), ('مبادرة أشجار تشرف عليها الإسكوا.', False, 'تشرف عليها هيئة البيئة.')],
 [('المؤسسات الحكومية', 'إصدار القوانين والدراسات البيئية', 'دور تنظيمي.'), ('المؤسسات الخاصة والأهلية', 'حملات التنظيف والتوعية والمسابقات', 'دور داعم.')],
 ('مسيرة العمل البيئي في عُمان', ['الاهتمام المبكر منذ بداية النهضة', 'إنشاء أول وزارة عربية للبيئة 1984م', 'إصدار القوانين والقرارات وتنفيذ المشاريع', 'شراكة المؤسسات الخاصة والأهلية', 'تدشين مكتب مساندة الاقتصاد الأخضر']))

lesson(2465,
 'أدى الانفجار السكاني والتقدم التكنولوجي وارتفاع مستوى المعيشة إلى قضايا بيئية منها النفايات، وهي مواد ليس لها قيمة للاحتفاظ بها، وتتعدد أنواعها وطرق التخلص منها.',
 [('يحدد العوامل المؤثرة سلبًا في البيئة', ['الانفجار السكاني.', 'التقدم العلمي والتكنولوجي وارتفاع مستوى المعيشة.']),
  ('يعرّف النفايات ويصنّف أنواعها', ['الصلبة: مخلفات المنازل والمصانع والمتاجر والمدارس والمزارع والبناء.', 'السائلة: مياه الصرف والتصنيع والتعدين والسوائل المترشحة. الغازية: أكاسيد الكربون والميثان وأكاسيد الكبريت والكلوروفلوروكربون.']),
  ('يقارن بين طرق التخلص من النفايات', ['الدفن، الحرق، إعادة التدوير، التسميد.', 'إعادة الاستخدام، التغويز البلازمي (أكثر من 1000 درجة فهرنهايت)، التقليل.'])],
 [('النفايات', 'مواد ليس لها قيمة للاحتفاظ بها'), ('إدارة النفايات', 'عمليات جمع ونقل ومعالجة النفايات للتخلص منها'), ('إعادة التدوير', 'تحويل النفايات إلى منتجات جديدة'), ('التسميد', 'ترك الفضلات العضوية فتحللها الكائنات الدقيقة إلى سماد')],
 ['النفايات الخطرة تحظى باهتمام دولي لآثارها الضارة.', 'التقليل من النفايات يسهم في المحافظة على البيئة وديمومتها.', 'إعادة التدوير من أساليب الاستدامة البيئية.'],
 'تصنيف النفايات إلى أنواعها الثلاثة، والتمييز بين طرق التخلص المتشابهة.', E,
 'كل يوم نرمي أشياء لا نحتاجها: أوراق وبقايا طعام وعلب. هذه نفايات، بعضها صلب وبعضها سائل وبعضها غاز يخرج من المصانع والسيارات. ويمكن التخلص منها بطرق مختلفة: ندفنها، أو نحوّلها لأشياء جديدة، أو نجعل بقايا الطعام سمادًا، والأفضل أن نقلل منها أصلًا.',
 [('النفايات مواد ليس لها ...... للاحتفاظ بها', 'قيمة'), ('مياه الصرف الصحي نفايات ......', 'سائلة'), ('تحويل النفايات إلى منتجات جديدة يسمى إعادة ......', 'التدوير'), ('الميثان من النفايات ......', 'الغازية')],
 [('مخلفات البناء نفايات (صلبة / غازية).', 'صلبة'), ('استخدام العنصر مرارًا في هيئته الأصلية (إعادة الاستخدام / إعادة التدوير).', 'إعادة الاستخدام'), ('تحويل الفضلات العضوية إلى سماد (التسميد / الحرق).', 'التسميد'), ('ترشيد الاستهلاك وتقليل حجم النفايات (التقليل / الدفن).', 'التقليل')],
 [('اذكر ثلاثة عوامل أثرت سلبًا في البيئة.', 'الانفجار السكاني، والتقدم العلمي والتكنولوجي، وارتفاع مستوى المعيشة.'), ('عرّف إدارة النفايات.', 'عمليات جمع ونقل ومعالجة النفايات للتخلص منها.'), ('ما الفرق بين الحرق والتغويز البلازمي؟', 'الحرق يحوّل النفايات إلى رماد وغاز وحرارة، والتغويز البلازمي يحوّلها إلى غاز البلازما بحرارة تزيد على 1000 درجة فهرنهايت.')],
 [('النفايات صلبة فقط.', False, 'هناك نفايات صلبة وسائلة وغازية.'), ('إعادة التدوير تحوّل النفايات إلى منتجات جديدة.', True, 'وهي من أساليب الاستدامة البيئية.'), ('التسميد طريقة مناسبة للتخلص من البلاستيك.', False, 'التسميد للفضلات العضوية فقط.'), ('ارتفاع مستوى المعيشة من العوامل المؤثرة سلبًا في البيئة.', True, 'مع الانفجار السكاني والتقدم التكنولوجي.')],
 [('بقايا الطعام', 'التسميد', 'فضلات عضوية تتحلل إلى سماد.'), ('القوارير البلاستيكية', 'إعادة التدوير', 'تتحول إلى منتجات جديدة.')],
 ('إدارة النفايات', ['جمع النفايات', 'نقل النفايات', 'معالجة النفايات', 'التخلص الآمن منها']))

lesson(2466,
 'شهدت سلطنة عُمان نقلة نوعية في إدارة النفايات بتكاتف المؤسسات الحكومية والخاصة: تشريعات وحاويات فصل ومحطات تحويلية ومرادم هندسية وبحوث وتوعية.',
 [('يعدّد جهود عُمان في إدارة النفايات', ['إصدار القوانين، وتوفير حاويات الفصل، وإنشاء محطات تحويلية ومرادم حديثة.', 'الاستفادة من تجارب الدول المتقدمة، والبحوث والدراسات، والبرامج التوعوية.', 'الانضمام إلى اتفاقية ميناماتا بشأن الزئبق 2020م.']),
  ('يحلّل مكونات المردم الهندسي', ['طبقة عازلة لحماية التربة، وطبقة تصريف المرشحات.', 'محطات معالجة الغاز والمرشحات، وآبار مراقبة المياه الجوفية، ومحطة مراقبة الهواء.']),
  ('يقترح بدائل للبلاستيك', ['الأكياس القماشية والورقية.', 'العبوات القابلة لإعادة الاستخدام.'])],
 [('المردم الهندسي', 'موقع مجهز لدفن النفايات بطبقات عازلة وأنظمة مراقبة ومعالجة'), ('المحطة التحويلية', 'محطة تُجمع فيها النفايات وتُفرز قبل نقلها'), ('المرشحات', 'السوائل التي ترشح من النفايات المدفونة')],
 ['اتفاقية ميناماتا تخص الزئبق.', 'التخلص السليم من النفايات مسؤولية مشتركة.', 'التقليل من النفايات يسهم في ديمومة البيئة.'],
 'تذكر جهود عُمان، وربط كل مكون في المردم بوظيفته.', E,
 'تفصل عُمان النفايات في حاويات مختلفة، ثم تنقلها إلى محطات ومرادم حديثة. والمردم ليس حفرة عادية؛ ففيه طبقة تحمي التربة، وأنابيب تجمع الغاز والسوائل لمعالجتها، وآبار تراقب الماء تحت الأرض حتى لا يتلوث.',
 [('انضمت عُمان إلى اتفاقية ...... بشأن الزئبق', 'ميناماتا'), ('توفر عُمان حاويات مخصصة لـ ...... النفايات', 'فصل'), ('الطبقة العازلة في المردم لحماية ......', 'التربة'), ('آبار المراقبة في المردم لمراقبة جودة المياه ......', 'الجوفية')],
 [('انضمت عُمان لاتفاقية ميناماتا عام (2020م / 2007م).', '2020م'), ('من جهود عُمان (إنشاء مرادم حديثة / حرق النفايات في الأودية).', 'إنشاء مرادم حديثة'), ('محطة معالجة الغاز جزء من (المردم الهندسي / مكتب الإسكوا).', 'المردم الهندسي'), ('بديل الأكياس البلاستيكية (الأكياس القماشية / الأكياس السوداء).', 'الأكياس القماشية')],
 [('اذكر ثلاثًا من جهود عُمان في إدارة النفايات.', 'إصدار القوانين، وتوفير حاويات الفصل، وإنشاء المحطات التحويلية والمرادم الحديثة.'), ('ما وظيفة آبار المراقبة في المردم؟', 'مراقبة جودة المياه الجوفية.'), ('اقترح بديلًا صديقًا للبيئة للبلاستيك.', 'الأكياس القماشية أو الورقية.')],
 [('المردم الهندسي حفرة مكشوفة بلا حماية.', False, 'مبطن بطبقة عازلة ومزود بأنظمة معالجة ومراقبة.'), ('انضمت عُمان إلى اتفاقية ميناماتا بشأن الزئبق.', True, 'عام 2020م.'), ('من جهود عُمان تنظيم برامج توعوية عن النفايات.', True, 'موجهة لمختلف أفراد المجتمع.'), ('تدير المؤسسات الحكومية وحدها النفايات في عُمان.', False, 'تتكاتف جهود المؤسسات الحكومية والخاصة.')],
 [('الطبقة العازلة', 'حماية التربة', 'في المردم الهندسي.'), ('آبار المراقبة', 'مراقبة جودة المياه الجوفية', 'في المردم الهندسي.')],
 ('رحلة النفايات المنزلية', ['الفصل في الحاويات المخصصة', 'الجمع والنقل إلى المحطة التحويلية', 'الفرز والمعالجة', 'الدفن في المردم الهندسي أو التدوير']))

lesson(2467,
 'انقراض الحيوانات قضية بيئية عالمية تحدث بوفاة آخر حيوان قادر على التكاثر من الفصيلة، ولها أسباب طبيعية وبشرية، وتبذل عُمان جهودًا لحماية حيواناتها المهددة.',
 [('يعرّف الانقراض ويعطي أمثلة', ['عالميًا: النمر السيبيري ووحيد القرن الأسود وسلحفاة منقار الصقر.', 'في عُمان: النمر العربي والوشق والمها العربية وسلاحف الريماني والشرفاف والصقر الأدهم.']),
  ('يستنتج الأسباب البشرية', ['الصيد الجائر للغذاء أو لأغراض تجارية، وتدمير المواطن أو تجزئتها.', 'تغيير الموطن الطبيعي، وإدخال أنواع جديدة تقضي على أنواع أخرى.']),
  ('يتتبع جهود عُمان', ['الانضمام إلى اتفاقية الاتجار الدولي بالأنواع المهددة 2007م.', 'قانون المحميات الطبيعية وصون الأحياء الفطرية (6/2003)، ومحميات كجبل سمحان (ظفار) والسّرين (مسقط).', 'الأبحاث والدراسات والندوات والمؤتمرات.'])],
 [('انقراض الحيوانات', 'زوال فصيلة بوفاة آخر حيوان قادر على التكاثر منها'), ('المحمية الطبيعية', 'مساحة محددة تتمتع بحماية خاصة لصون بيئتها أو حماية أنواع من الكائنات'), ('الصيد الجائر', 'الصيد المفرط الذي يهدد بقاء الأنواع')],
 ['الصقر الأدهم يعشش صيفًا على جزر الديمانيات وجزيرة الفحل.', 'حماية الحيوانات من الانقراض ضمان للتوازن البيئي.', 'خطاب السلطان قابوس 1992م نبّه إلى انقراض الحياة والغابات.'],
 'التمييز بين الأسباب الطبيعية والبشرية، وربط المحميات بمحافظاتها.', E,
 'بعض الحيوانات قلّ عددها كثيرًا حتى كادت تختفي، مثل النمر العربي والمها العربية. والسبب غالبًا الإنسان: يصطادها كثيرًا أو يهدم بيوتها الطبيعية. لذلك أنشأت عُمان محميات يُمنع فيها الصيد، ووضعت قوانين تعاقب من يؤذي هذه الحيوانات.',
 [('تنقرض الفصيلة بوفاة آخر حيوان قادر على ......', 'التكاثر'), ('تقع محمية جبل سمحان في محافظة ......', 'ظفار'), ('انضمت عُمان إلى اتفاقية الاتجار الدولي بالأنواع المهددة عام ......م', '2007'), ('تقع محمية السّرين في محافظة ......', 'مسقط')],
 [('الصيد الجائر سبب (بشري / طبيعي).', 'بشري'), ('قانون المحميات الطبيعية صدر بالمرسوم (6/2003 / 114/2001).', '6/2003'), ('من الحيوانات المهددة في عُمان (المها العربية / النمر السيبيري).', 'المها العربية'), ('يعشش الصقر الأدهم على جزر (الديمانيات / الحلانيات).', 'الديمانيات')],
 [('عرّف المحمية الطبيعية.', 'مساحة جغرافية محددة تتمتع بحماية خاصة لصون بيئتها الطبيعية أو الثقافية أو لحماية نوع من الحيوانات أو النباتات.'), ('اذكر سببين بشريين للانقراض.', 'الصيد الجائر، وتدمير المواطن الطبيعية (أو إدخال أنواع جديدة).'), ('اذكر إجراءين لحماية الحيوانات المهددة في عُمان.', 'الانضمام إلى الاتفاقيات الدولية، وإعلان المحميات الطبيعية.')],
 [('الانقراض يحدث بانخفاض أعداد الفصيلة إلى النصف.', False, 'يحدث بوفاة آخر حيوان قادر على التكاثر منها.'), ('إدخال أنواع جديدة قد يقضي على أنواع أخرى.', True, 'من الأسباب البشرية للانقراض.'), ('محمية جبل سمحان في محافظة مسقط.', False, 'في محافظة ظفار؛ أما السّرين ففي مسقط.'), ('النمر العربي من الحيوانات المعرضة للانقراض في عُمان.', True, 'مع الوشق والمها العربية وبعض السلاحف البحرية.')],
 [('محمية جبل سمحان', 'محافظة ظفار', 'من المحميات الطبيعية العُمانية.'), ('محمية السّرين', 'محافظة مسقط', 'من المحميات الطبيعية العُمانية.')],
 ('كيف تحمي عُمان الحيوانات المهددة؟', ['رصد الأنواع المهددة بالأبحاث والدراسات', 'الانضمام إلى الاتفاقيات الدولية', 'إصدار قانون المحميات الطبيعية وصون الأحياء الفطرية', 'إعلان المحميات الطبيعية']))

UNITS = {
 '1': dict(title='عُمان.. تاريخ وحضارة',
   big=['عصر النباهنة (نحو خمسة قرون): تجزئة سياسية وصراعات، مع منجزات حضارية، وانتهى بالغزو البرتغالي (1507م).', 'عصر اليعاربة (1624م): توحيد البلاد وطرد البرتغاليين وازدهار حضاري، ثم النهاية بتنافس البيت اليعربي.', 'عصر البوسعيد (1744م): منجزات سياسية وعسكرية وإمبراطورية واسعة، وتُوّج بالنهضة الحديثة (1970م) والانتقال السلس للحكم (2020م).', 'الوحدة الوطنية سرّ القوة والاستقلال، وغيابها يقود إلى التفكك والغزو.'],
   conn='تتتبع الوحدة ثلاثة عصور متتالية: تبدأ بعصر النباهنة وتجزئته التي مهدت للغزو البرتغالي، ثم عصر اليعاربة الذي أعاد الوحدة وطرد البرتغاليين، ثم عصر البوسعيد الذي بنى الإمبراطورية ووصل بعُمان إلى النهضة الحديثة.',
   check=['قارن بين أوضاع عُمان في عصري النباهنة واليعاربة.', 'رتّب: تحرير مسقط ومطرح، بداية عصر البوسعيد، وصول البرتغاليين جزر الحلانيات، النهضة الحديثة.', 'اذكر منجزًا عمرانيًا واحدًا لكل عصر.', 'علّل: الوحدة الوطنية سرّ قوة الدولة.']),
 '2': dict(title='بيئتنا.. تنوع وثراء واستدامة',
   big=['البيئة طبيعية ومشيّدة تتفاعلان إيجابًا أو سلبًا، والتنوع الأحيائي أساس التوازن البيئي.', 'تعدّ عُمان البيئة المحلية جزءًا من البيئة العالمية فتعقد المؤتمرات وتصادق على الاتفاقيات وخصصت جائزة اليونسكو – السلطان قابوس.', 'توازن عُمان بين التنمية وحماية البيئة بالخطط والتشريعات والمؤسسات الحكومية والأهلية.', 'من القضايا البيئية النفايات وانقراض الحيوانات، ولعُمان جهود في إدارة النفايات والمحميات الطبيعية.'],
   conn='تنطلق الوحدة من مفهوم البيئة والتنوع الأحيائي عالميًا، ثم تنتقل إلى البيئة العُمانية وتنوعها وجهود حمايتها، وتختم بقضيتين بيئيتين (النفايات والانقراض) وجهود عُمان في مواجهتهما.',
   check=['فرّق بين البيئة الطبيعية والمشيّدة.', 'اذكر ثلاثًا من جهود عُمان لحماية البيئة العالمية.', 'اذكر تشريعين بيئيين عُمانيين.', 'قارن بين إعادة التدوير وإعادة الاستخدام، واذكر سببين بشريين لانقراض الحيوانات.']),
}
